package org.sleepwell.app;

import android.content.*;
import android.database.sqlite.SQLiteDatabase;
import android.net.Uri;
import android.os.*;
import org.json.JSONObject;
import java.io.*;
import java.lang.ref.WeakReference;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;

/** A pinned read-only original-source projection and explicit retained single-record CSV export. */
final class SleepCsvSourceJob implements AutoCloseable {
    enum Phase {EMPTY,LOADING,READY,CHOOSING,WRITING,CANCELLING,ERROR}
    static final class Data {final RecordEntry record;final SleepCsvFormat.Entry source;final SleepCsvFormat.SourceSignals signals;Data(RecordEntry record,SleepCsvFormat.Entry source,SleepCsvFormat.SourceSignals signals){this.record=record;this.source=source;this.signals=signals;}}
    interface Observer {void changed();}
    private static final Semaphore EXPORT=new Semaphore(1);private static final Executor CANCEL=new ThreadPoolExecutor(0,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(2),r->new Thread(r,"csv-source-close"),new ThreadPoolExecutor.DiscardPolicy());
    final Context app;final Records.Factory records;final long id;final ExecutorService worker=Executors.newSingleThreadExecutor();final Handler main=new Handler(Looper.getMainLooper());final AtomicReference<CancellationSignal> signal=new AtomicReference<>();final AtomicReference<ParcelFileDescriptor> descriptor=new AtomicReference<>();private WeakReference<Observer> observer=new WeakReference<>(null);volatile int generation;volatile boolean closed;Phase phase=Phase.EMPTY;Data data;String message="";int request=20000+ThreadLocalRandom.current().nextInt(10000);
    SleepCsvSourceJob(Context context,long id){app=context.getApplicationContext();records=Records.factory;this.id=id;load();}
    void observe(Observer target){observer=new WeakReference<>(target);target.changed();}void detach(Observer target){if(observer.get()==target)observer.clear();}private void publish(){if(closed)return;Observer target=observer.get();if(target!=null)target.changed();}
    boolean busy(){return phase==Phase.LOADING||phase==Phase.CHOOSING||phase==Phase.WRITING||phase==Phase.CANCELLING;}
    private boolean active(int ticket){return !closed&&generation==ticket&&!Thread.currentThread().isInterrupted();}
    private Data read(Store store,int ticket)throws Exception {if(id<=0)throw new IOException("Choose an imported CSV period.");SQLiteDatabase db=store.getReadableDatabase();db.beginTransactionNonExclusive();try{NightAudioArchive.active(()->active(ticket));RecordEntry record=Records.get(store,id);List<JSONObject> sources=store.rows("SELECT source_id,sha256,csv FROM sleep_csv_sources WHERE session=?",""+id);if(sources.size()!=1)throw new IOException("This record has no imported CSV source, or it was removed.");JSONObject row=sources.get(0);String raw=row.getString("csv");if(raw.getBytes(StandardCharsets.UTF_8).length>SleepCsvEvidence.MAX_BYTES)throw new IOException("The source record exceeds the supported size.");SleepCsvFormat.Entry source=SleepCsvFormat.one(raw);if(!source.sha256.equals(row.getString("sha256"))||!source.sourceId.equals(row.getString("source_id"))||!record.manual()||!record.origin.equals("imported")||record.rawStart!=source.start||record.rawEnd!=source.end||!record.zone.equals(source.zone))throw new IOException("The source evidence no longer matches this period.");SleepCsvFormat.SourceSignals signals=SleepCsvFormat.signals(source,()->active(ticket));NightAudioArchive.active(()->active(ticket));db.setTransactionSuccessful();return new Data(record,source,signals);}finally{db.endTransaction();}}
    void load(){if(closed||busy())return;int ticket=++generation;phase=Phase.LOADING;message="Reading original CSV signals…";publish();worker.execute(()->{try(Store store=records.open(app)){Data result=read(store,ticket);main.post(()->{if(active(ticket)){data=result;phase=Phase.READY;message="";publish();}});}catch(Exception failure){main.post(()->{if(active(ticket)){data=null;phase=Phase.ERROR;message=notice(failure,"Source signals could not be loaded.");publish();}});}});}
    boolean choose(){if(closed||phase!=Phase.READY||data==null)return false;request=request>=60000?20000:request+1;phase=Phase.CHOOSING;message="Choose a location for this original single-record CSV.";publish();return true;}
    void cancelChoice(){if(phase!=Phase.CHOOSING)return;request=request>=60000?20000:request+1;phase=Phase.READY;message="Export cancelled. No destination was written.";publish();}
    void write(Uri uri){if(closed||phase!=Phase.CHOOSING||data==null)return;if(uri==null||!"content".equals(uri.getScheme())||uri.getAuthority()==null){phase=Phase.READY;message="Choose an Android document destination.";publish();return;}Data reviewed=data;int ticket=++generation;phase=Phase.WRITING;message="Verifying and exporting the exact original rows…";publish();worker.execute(()->{boolean admitted=false;try{if(!EXPORT.tryAcquire())throw new IOException("An earlier CSV source export is still closing.");admitted=true;try(Store store=records.open(app)){Data current=read(store,ticket);if(current.record.updated!=reviewed.record.updated||!current.source.sha256.equals(reviewed.source.sha256))throw new IOException("The record changed. Refresh before exporting its original source.");}byte[] bytes=reviewed.source.raw.getBytes(StandardCharsets.UTF_8);CancellationSignal cancellation=new CancellationSignal();signal.set(cancellation);try{NightAudioArchive.active(()->active(ticket));ParcelFileDescriptor file=app.getContentResolver().openFileDescriptor(uri,"wt",cancellation);if(file==null)throw new IOException("Destination unavailable.");descriptor.set(file);try(OutputStream output=new ParcelFileDescriptor.AutoCloseOutputStream(file)){for(int at=0;at<bytes.length;){NightAudioArchive.active(()->active(ticket));int n=Math.min(16384,bytes.length-at);output.write(bytes,at,n);at+=n;}output.flush();}finally{descriptor.compareAndSet(file,null);}}finally{signal.compareAndSet(cancellation,null);}main.post(()->{if(active(ticket)){phase=Phase.READY;message="Original single-record CSV exported. The saved record was unchanged.";publish();}});}catch(Exception failure){main.post(()->{if(active(ticket)){phase=Phase.READY;message=notice(failure,"Source export failed.")+" The destination may contain an empty or partial file.";publish();}});}finally{if(admitted)EXPORT.release();main.post(()->{if(!closed&&phase==Phase.CANCELLING){phase=Phase.READY;message="Export cancelled. Remove any empty or partial destination file.";publish();}});}});}
    void cancelExport(){if(phase==Phase.CHOOSING){cancelChoice();return;}if(closed||phase!=Phase.WRITING)return;generation++;phase=Phase.CANCELLING;message="Closing the export…";cancelProvider();publish();}
    private void cancelProvider(){CancellationSignal cancellation=signal.get();ParcelFileDescriptor file=descriptor.get();CANCEL.execute(()->{if(cancellation!=null)try{cancellation.cancel();}catch(RuntimeException ignored){}if(file!=null)try{file.close();}catch(IOException ignored){}});}
    private static String notice(Exception error,String fallback){return error instanceof IOException&&error.getMessage()!=null?error.getMessage():fallback;}
    public void close(){if(closed)return;closed=true;generation++;observer.clear();cancelProvider();worker.shutdownNow();}
}
